CUME_DIST.syntax:
exp_name = CUME_DIST( ) OVER (
  [PARTITION BY expression{,expression}]
  ORDER BY expression[DESC],{expression[DESC]}
  )

 exp_name =  CUME_DIST( constant,{constant} ) WITHIN GROUP ( ORDER BY expression[DESC],{expression[DESC]})

